import{_ as s,a0 as p,w as m,s as i,ao as l,I as n,x as t,a1 as r,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"彭博社開源 Memray，一個 Python 內存剖析器 | LCTT x X-CMD","titleTemplate":false,"description":"彭博社開源 Memray，一個 Python 內存剖析器 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"彭博社開源 Memray，一個 Python 內存剖析器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"彭博社開源 Memray，一個 Python 內存剖析器 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220427 Bloomberg Open Sources Memray, A Python Memory Profiler","title":"彭博社開源 Memray，一個 Python 內存剖析器","tag":"202205","desc":""},"relativePath":"202205/20220427 Bloomberg Open Sources Memray, A Python Memory Profiler.md","filePath":"[post].md"}'),y={name:"202205/20220427 Bloomberg Open Sources Memray, A Python Memory Profiler.md"};function u(d,e,h,f,g,b){const o=p("Link");return m(),i("div",null,[e[15]||(e[15]=l(`<h1 id="彭博社開源-memray-一個-python-內存剖析器" tabindex="-1">彭博社開源 Memray，一個 Python 內存剖析器 <a class="header-anchor" href="#彭博社開源-memray-一個-python-內存剖析器" aria-label="Permalink to “彭博社開源 Memray，一個 Python 內存剖析器”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202205/12/081556a84j8f331irlszo2.jpg" alt=""></p><p>Memray 是一個由彭博社開發的<ruby>內存剖析器<rt>memory profiler</rt></ruby>，現在已經開源。它可以跟蹤 Python 代碼中的內存分配，包括本地擴展和 Python 解釋器本身。內存剖析是瞭解程序如何利用內存的有力工具，因此可以檢測內存泄漏或確定程序中哪些區域消耗的內存最多。</p><p>與 py-spy 等抽樣內存剖析器相比，Memray 可以跟蹤每個函數調用，包括對 C/C++ 庫的調用，並詳細顯示調用棧。彭博社稱，這並不以犧牲性能為代價，剖析只使解釋代碼的速度變慢一點。然而，原生代碼剖析的速度較慢，因此需要直接啓用。</p><p>Memray 可以根據獲得的內存消耗數據生成各種報告，包括火焰圖，這對快速、準確地識別最常見的代碼路徑很有價值。</p><p>據 EgdeDB 的聯合創始人兼 CEO Yury Selivanov 稱，該工具提供了以前無法獲得的對 Python 應用的洞察力。Memray 可以用來從命令列中執行和剖析 Python 應用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python3 -m memray run -o output.bin my_script.py</span></span>
<span class="line"><span>$ python3 -m memray flamegraph output.bin</span></span></code></pre></div><p>另外，你可以使用 pytest-memray 將 Memray 集成到你的測試套件中。你也可以用 <code>-native</code> 命令列選項對所有的 C/C++ 調用進行剖析，或者用 <code>-live</code> 命令列選項在程序執行過程中實時分析內存分配。Memray 可以在 Linux x86/64 系統上用 <code>python3 -m pip install memray</code> 來安裝。</p><p>（題圖由 Frantisek Krejci 在 Pixabay 上發佈）</p><hr>`,10)),n("p",null,[e[1]||(e[1]=t("via: ",-1)),r(o,{href:"https://www.opensourceforu.com/2022/04/bloomberg-open-sources-memray-a-python-memory-profiler/"},{default:a(()=>[...e[0]||(e[0]=[t("https://www.opensourceforu.com/2022/04/bloomberg-open-sources-memray-a-python-memory-profiler/",-1)])]),_:1})]),n("p",null,[e[6]||(e[6]=t("作者：",-1)),r(o,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:a(()=>[...e[2]||(e[2]=[t("Laveesh Kocher",-1)])]),_:1}),e[7]||(e[7]=t(" 選題：",-1)),r(o,{href:"https://github.com/lkxed"},{default:a(()=>[...e[3]||(e[3]=[t("lkxed",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),r(o,{href:"https://github.com/geekpi"},{default:a(()=>[...e[4]||(e[4]=[t("geekpi",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:a(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[12]||(e[12]=t("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創編譯，",-1)),r(o,{href:"https://linux.cn/"},{default:a(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const T=s(y,[["render",u]]);export{C as __pageData,T as default};
